import React, { useCallback } from 'react';
import { TableData, ColumnMetadata } from '../types';

interface Props {
  onUploadSuccess: (data: TableData) => void;
  isLoading: boolean;
  setIsLoading: (val: boolean) => void;
}

// Global libraries
declare var XLSX: any;
declare var Papa: any;

const FileUploader: React.FC<Props> = ({ onUploadSuccess, isLoading, setIsLoading }) => {

  const detectType = (value: any): ColumnMetadata['type'] => {
    if (typeof value === 'number') return 'number';
    if (typeof value === 'boolean') return 'boolean';
    if (!isNaN(Date.parse(value)) && isNaN(value)) return 'date';
    return 'string';
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsLoading(true);

    const reader = new FileReader();
    reader.onload = (event) => {
      const data = event.target?.result;
      const extension = file.name.split('.').pop()?.toLowerCase();

      if (extension === 'csv') {
        Papa.parse(file, {
          header: true,
          dynamicTyping: true,
          skipEmptyLines: true,
          complete: (results: any) => {
            processParsedData(results.data, file.name);
          }
        });
      } else if (['xlsx', 'xls'].includes(extension || '')) {
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        processParsedData(jsonData, file.name);
      } else {
        alert('Unsupported file format. Please upload CSV or Excel.');
        setIsLoading(false);
      }
    };

    if (file.name.endsWith('.csv')) {
      reader.readAsText(file);
    } else {
      reader.readAsBinaryString(file);
    }
  };

  const processParsedData = (rows: any[], fileName: string) => {
    if (!rows.length) {
      alert('File is empty.');
      setIsLoading(false);
      return;
    }

    const firstRow = rows[0];
    const columns: ColumnMetadata[] = Object.keys(firstRow).map(key => ({
      name: key,
      type: detectType(firstRow[key])
    }));

    onUploadSuccess({ columns, rows, fileName });
    setIsLoading(false);
  };

  return (
    <div className="bg-white p-8 rounded-xl border border-gray-200 shadow-sm transition-all hover:shadow-md">
      <div className="flex flex-col items-center justify-center space-y-4">
        <div className="p-4 bg-indigo-50 rounded-full">
          <svg className="w-12 h-12 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
          </svg>
        </div>
        <div className="text-center">
          <h3 className="text-lg font-semibold text-gray-900">Upload your data</h3>
          <p className="text-sm text-gray-500 mt-1">CSV or Excel files (max 10MB)</p>
        </div>
        <div className="w-full max-w-xs">
          <label className={`block w-full text-center px-4 py-3 rounded-lg border-2 border-dashed border-gray-300 cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all ${isLoading ? 'opacity-50 pointer-events-none' : ''}`}>
            <span className="text-sm font-medium text-gray-700">
              {isLoading ? 'Processing...' : 'Click to browse files'}
            </span>
            <input type="file" className="hidden" accept=".csv,.xlsx,.xls" onChange={handleFileChange} />
          </label>
        </div>
      </div>
    </div>
  );
};

export default FileUploader;

import React from 'react';

interface Props {
  data: any[];
  columns: string[];
  title?: string;
  maxRows?: number;
}

const DataTable: React.FC<Props> = ({ data, columns, title, maxRows = 100 }) => {
  const displayData = data.slice(0, maxRows);

  if (!data || data.length === 0) {
    return (
      <div className="p-12 text-center bg-gray-50 border border-dashed border-gray-200 rounded-xl">
        <p className="text-gray-500">No data to display</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col space-y-3">
      {title && <h4 className="text-sm font-semibold text-gray-700 uppercase tracking-wider">{title}</h4>}
      <div className="overflow-x-auto border border-gray-200 rounded-xl shadow-sm bg-white">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              {columns.map((col, idx) => (
                <th key={idx} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider whitespace-nowrap">
                  {col}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {displayData.map((row, rowIdx) => (
              <tr key={rowIdx} className="hover:bg-gray-50 transition-colors">
                {columns.map((col, colIdx) => (
                  <td key={colIdx} className="px-4 py-3 whitespace-nowrap text-sm text-gray-600 font-medium">
                    {row[col]?.toString() ?? <span className="text-gray-300 italic">null</span>}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
        {data.length > maxRows && (
          <div className="px-4 py-3 bg-gray-50 text-xs text-gray-500 border-t border-gray-200 text-center">
