export default DataTable;

import React, { useState } from 'react';
import { GeminiService } from '../services/gemini.ts';
import { DataService } from '../services/db.ts';
import { TableData, QueryResult } from '../types.ts';

interface Props {
  tableData: TableData;
  onQueryResult: (result: QueryResult) => void;
}

const QueryInterface: React.FC<Props> = ({ tableData, onQueryResult }) => {
  const [query, setQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim() || isProcessing) return;

    setIsProcessing(true);
    setError(null);

    try {
      // 1. Get SQL from AI
      const aiResponse = await GeminiService.generateSQL(
        query,
        tableData.columns,
        tableData.rows.slice(0, 5)
      );

      if (aiResponse.isAmbiguous) {
        setError(`Ambiguous query: ${aiResponse.clarificationMessage}`);
        setIsProcessing(false);
        return;
      }

      // 2. Execute SQL via DataService
      const results = await DataService.executeQuery(aiResponse.sql);

      // 3. Return results to parent
      onQueryResult({
        sql: aiResponse.sql,
        explanation: aiResponse.explanation,
        data: results
      });
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred.');
    } finally {
      setIsProcessing(false);
    }
  };

  const suggestions = [
    "Show me the top 10 items",
    "How many records are there?",
    "Filter where value is greater than 100",
    "Average of column values"
  ];

  return (
    <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm space-y-6">
      <div className="space-y-2">
        <label className="text-sm font-semibold text-gray-700">Ask a question about your data</label>
        <form onSubmit={handleAsk} className="flex flex-col sm:flex-row gap-3">
          <input
            type="text"
            className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all placeholder:text-gray-400"
            placeholder="e.g. What is the total revenue by region?"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            disabled={isProcessing}
          />
          <button
            type="submit"
            disabled={isProcessing || !query.trim()}
            className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-gray-400 text-white font-semibold py-3 px-8 rounded-lg transition-all flex items-center justify-center space-x-2 whitespace-nowrap shadow-md hover:shadow-lg"
          >
            {isProcessing ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <span>Analyzing...</span>
              </>
            ) : (
              <span>Ask AI</span>
            )}
          </button>
        </form>
      </div>

      {error && (
        <div className="p-4 bg-red-50 border border-red-200 text-red-700 rounded-lg text-sm flex items-start space-x-2">
          <svg className="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
          </svg>
          <span>{error}</span>
        </div>
      )}

      <div className="flex flex-wrap gap-2">
        {suggestions.map((s, i) => (
          <button
            key={i}
            onClick={() => setQuery(s)}
            className="text-xs px-3 py-1.5 bg-gray-50 border border-gray-200 text-gray-600 rounded-full hover:bg-indigo-50 hover:text-indigo-600 hover:border-indigo-200 transition-all"
          >
            {s}
          </button>
        ))}
      </div>
    </div>
  );
};

export default QueryInterface;

import React, { useState, useEffect } from 'react';
