              </div>
              <button 
                onClick={reset}
                className="text-sm font-medium text-red-600 hover:text-red-700 px-4 py-2 border border-red-100 bg-red-50 rounded-lg transition-colors"
              >
                Reset
              </button>
            </div>

            <QueryInterface 
