            {/* Results Preview */}
            {queryResult ? (
              <div className="space-y-6">
                <div className="bg-indigo-50 border border-indigo-100 p-5 rounded-xl space-y-3">
                  <div className="flex items-center space-x-2">
                    <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0116 0z" />
                    </svg>
                    <span className="text-sm font-bold text-indigo-900 uppercase tracking-tight">AI Insight</span>
                  </div>
                  <p className="text-indigo-800 text-sm leading-relaxed">{queryResult.explanation}</p>
                  <div className="bg-white/50 p-3 rounded-lg border border-indigo-200">
                    <code className="text-xs font-mono text-indigo-600 break-all">{queryResult.sql}</code>
