        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <p>&copy; 2024 AskCSV AI. Read-only queries. Private & Secure.</p>
          <div className="flex items-center space-x-4">
             <span className="flex items-center text-green-500">
                <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                System Status: Active
             </span>
             <a href="#" className="hover:text-indigo-600">Privacy Policy</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import { TableData } from '../types';

// Declare global library from index.html
declare var alasql: any;
declare var XLSX: any;
declare var Papa: any;
declare var jspdf: any;

export class DataService {
  private static tableName = 'uploaded_data';

  static async initTable(data: TableData): Promise<void> {
    try {
      // Clear existing table if any
      alasql(`DROP TABLE IF EXISTS ${this.tableName}`);

      // Create table structure
      const colDefs = data.columns.map(col => `\`${col.name}\``).join(', ');
      alasql(`CREATE TABLE ${this.tableName} (${colDefs})`);

      // Bulk insert data
      alasql.tables[this.tableName].data = data.rows;
    } catch (error) {
      console.error('Error initializing database:', error);
      throw new Error('Failed to initialize database session.');
    }
  }

  static async executeQuery(sql: string): Promise<any[]> {
    try {
      // Security Check: Only allow SELECT
      const trimmedSql = sql.trim().toUpperCase();
      if (!trimmedSql.startsWith('SELECT')) {
        throw new Error('Unauthorized query: Only SELECT statements are allowed.');
      }

      // Ensure the table name is correct
      // Simple regex replacement if AI didn't follow the table name rule perfectly
      const safeSql = sql.replace(/FROM\s+\w+/i, `FROM ${this.tableName}`);

      const result = alasql(safeSql);
      return result;
    } catch (error: any) {
      console.error('SQL Execution Error:', error);
      throw new Error(error.message || 'Error executing SQL query.');
    }
  }

  static async downloadResultAsCSV(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;

    const csv = Papa.unparse(data);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', filename.endsWith('.csv') ? filename : `${filename}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  static async downloadResultAsExcel(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Results");
    XLSX.writeFile(workbook, filename.endsWith('.xlsx') ? filename : `${filename}.xlsx`);
  }

  static async downloadResultAsPDF(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;

    const doc = new jspdf.jsPDF();
    const columns = Object.keys(data[0]);
    const rows = data.map(item => columns.map(col => item[col]));

    // @ts-ignore
    doc.autoTable({
      head: [columns],
      body: rows,
      styles: { fontSize: 8 },
      margin: { top: 20 },
      didDrawPage: (dataArg: any) => {
        doc.text('AskCSV AI Query Results', 14, 15);
      }
    });

    doc.save(filename.endsWith('.pdf') ? filename : `${filename}.pdf`);
  }
}

