import { TableData } from '../types';

// Declare global libraries from index.html
declare var alasql: any;
declare var XLSX: any;
declare var Papa: any;
declare var jspdf: any;

export class DataService {
  private static tableName = 'uploaded_data';

  static async initTable(data: TableData): Promise<void> {
    try {
      // Clear existing table and cache if any
      if (alasql.tables[this.tableName]) {
        alasql(`DROP TABLE ${this.tableName}`);
      }

      // Create table structure with escaped column names
      const colDefs = data.columns.map(col => `\`${col.name}\``).join(', ');
      alasql(`CREATE TABLE ${this.tableName} (${colDefs})`);

      // Bulk insert data - AlaSQL can take the array directly
      alasql.tables[this.tableName].data = data.rows;

      console.log(`Database initialized with ${data.rows.length} rows.`);
    } catch (error) {
      console.error('Error initializing database:', error);
      throw new Error('Failed to initialize database session. Please try re-uploading.');
    }
  }

  static async executeQuery(sql: string): Promise<any[]> {
    try {
      // Security Check: Only allow SELECT
      const trimmedSql = sql.trim().toUpperCase();
      if (!trimmedSql.startsWith('SELECT')) {
        throw new Error('Unauthorized query: Only SELECT statements are allowed for security reasons.');
      }

      // Ensure the table name is correct. Gemini usually gets it right, 
      // but we force our table name for stability.
      let safeSql = sql;
      // Replace case-insensitive references to other table names if they exist
      if (!safeSql.toUpperCase().includes(this.tableName.toUpperCase())) {
         // Fallback regex attempt to swap whatever table was guessed with our real one
         safeSql = safeSql.replace(/FROM\s+([a-zA-Z0-9_]+)/i, `FROM ${this.tableName}`);
      }

      const result = alasql(safeSql);

      // AlaSQL returns nested arrays for some aggregate queries, flatten if necessary
      if (Array.isArray(result) && result.length > 0 && Array.isArray(result[0])) {
          return result[0];
      }

      return Array.isArray(result) ? result : [result];
    } catch (error: any) {
      console.error('SQL Execution Error:', error);
      throw new Error(error.message || 'Error executing the generated SQL. The AI might have used an incompatible syntax.');
    }
  }

  static async downloadResultAsCSV(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;
    const csv = Papa.unparse(data);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    this.triggerDownload(url, `${filename}.csv`);
  }

  static async downloadResultAsExcel(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "QueryResults");
    XLSX.writeFile(workbook, `${filename}.xlsx`);
  }

  static async downloadResultAsPDF(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;
    const { jsPDF } = jspdf;
    const doc = new jsPDF('l', 'mm', 'a4'); // Landscape for better data fitting
    const columns = Object.keys(data[0]);
    const rows = data.map(item => columns.map(col => item[col]));

    // @ts-ignore
    doc.autoTable({
      head: [columns],
      body: rows,
      theme: 'grid',
      styles: { fontSize: 7, cellPadding: 2 },
      headStyles: { fillColor: [79, 70, 229] }, // Indigo-600
      margin: { top: 25 },
      didDrawPage: (dataArg: any) => {
        doc.setFontSize(16);
        doc.text('AskCSV AI: Query Results', 14, 15);
        doc.setFontSize(10);
        doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 20);
      }
    });

    doc.save(`${filename}.pdf`);
  }

  private static triggerDownload(url: string, filename: string) {
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
}

import React, { useRef } from 'react';
import { TableData, ColumnMetadata } from '../types';

interface Props {
  onUploadSuccess: (data: TableData) => void;
  isLoading: boolean;
  setIsLoading: (val: boolean) => void;
}

declare var XLSX: any;
declare var Papa: any;

const FileUploader: React.FC<Props> = ({ onUploadSuccess, isLoading, setIsLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const detectType = (value: any): ColumnMetadata['type'] => {
    if (value === null || value === undefined) return 'string';
    if (typeof value === 'number') return 'number';
    if (typeof value === 'boolean') return 'boolean';
    if (typeof value === 'string') {
      // Basic check for Date strings
      const date = Date.parse(value);
      if (!isNaN(date) && value.length > 8 && (value.includes('-') || value.includes('/') || value.includes(':'))) {
        return 'date';
      }
    }
    return 'string';
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // 10MB limit for client-side processing to keep things smooth
    if (file.size > 10 * 1024 * 1024) {
      alert("File is too large. Please upload a file smaller than 10MB.");
      return;
    }

    setIsLoading(true);
    const extension = file.name.split('.').pop()?.toLowerCase();

    if (extension === 'csv') {
      Papa.parse(file, {
        header: true,
        dynamicTyping: true,
        skipEmptyLines: true,
        complete: (results: any) => {
          processParsedData(results.data, file.name);
        },
        error: (err: any) => {
          console.error(err);
          alert("Error parsing CSV: " + err.message);
          setIsLoading(false);
        }
      });
    } else if (['xlsx', 'xls', 'ods'].includes(extension || '')) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = new Uint8Array(event.target?.result as ArrayBuffer);
          const workbook = XLSX.read(data, { type: 'array' });
          const firstSheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[firstSheetName];
          const jsonData = XLSX.utils.sheet_to_json(worksheet);
          processParsedData(jsonData, file.name);
        } catch (err: any) {
          alert("Error reading Excel file: " + err.message);
          setIsLoading(false);
        }
      };
      reader.readAsArrayBuffer(file);
    } else {
      alert('Unsupported file format. Please upload CSV or Excel.');
      setIsLoading(false);
    }
  };

  const processParsedData = (rows: any[], fileName: string) => {
    if (!rows || rows.length === 0) {
      alert('The file appears to be empty or could not be read properly.');
      setIsLoading(false);
      return;
    }

    // Clean data: replace nested objects or complex types with strings for AlaSQL compatibility
    const cleanedRows = rows.map(row => {
        const newRow: any = {};
        for (const key in row) {
            const val = row[key];
            if (val !== null && typeof val === 'object' && !(val instanceof Date)) {
                newRow[key] = JSON.stringify(val);
            } else {
                newRow[key] = val;
            }
        }
        return newRow;
    });

    const firstRow = cleanedRows[0];
    const columns: ColumnMetadata[] = Object.keys(firstRow).map(key => ({
      name: key,
      type: detectType(firstRow[key])
    }));

    onUploadSuccess({ columns, rows: cleanedRows, fileName });
    setIsLoading(false);
  };

  return (
    <div className="bg-white p-10 rounded-2xl border border-gray-200 shadow-xl transition-all hover:border-indigo-300">
      <div className="flex flex-col items-center justify-center space-y-6">
        <div className="p-5 bg-indigo-50 rounded-2xl">
          <svg className="w-14 h-14 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
        </div>
        <div className="text-center space-y-2">
          <h3 className="text-2xl font-bold text-gray-900">Upload Data</h3>
          <p className="text-gray-500 max-w-sm">Drop your CSV or Excel file here to start querying with natural language.</p>
        </div>

        <div className="w-full">
          <input 
            type="file" 
            className="hidden" 
            ref={fileInputRef} 
            accept=".csv,.xlsx,.xls,.ods" 
            onChange={handleFileChange} 
          />
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={isLoading}
            className={`w-full flex items-center justify-center space-x-2 px-6 py-4 rounded-xl border-2 border-dashed transition-all 
              ${isLoading 
                ? 'bg-gray-50 border-gray-200 cursor-not-allowed' 
                : 'bg-indigo-50/50 border-indigo-200 hover:border-indigo-500 hover:bg-indigo-50 text-indigo-700'
              }`}
          >
            {isLoading ? (
              <>
                <svg className="animate-spin h-5 w-5 text-indigo-600" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <span className="font-semibold">Processing Data...</span>
              </>
            ) : (
              <>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                <span className="font-semibold">Select File</span>
              </>
            )}
          </button>
        </div>
        <p className="text-xs text-gray-400">Supported formats: .csv, .xlsx, .xls</p>
      </div>
    </div>
  );
};

