          </table>
        </div>
        {data.length > maxRows && (
          <div className="px-6 py-3 bg-gray-50/80 backdrop-blur-sm text-xs text-gray-500 border-t border-gray-200 flex justify-between items-center">
            <span>Showing first <b>{maxRows}</b> records</span>
