import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import DataTable from './components/DataTable';
import QueryInterface from './components/QueryInterface';
import QueryHistory from './components/QueryHistory';
import { TableData, QueryResult, QueryHistoryItem } from './types';
import { DataService } from './services/db';

const App: React.FC = () => {
  const [tableData, setTableData] = useState<TableData | null>(null);
  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [queryHistory, setQueryHistory] = useState<QueryHistoryItem[]>([]);
  const [selectedHistoryQuery, setSelectedHistoryQuery] = useState<string>('');
  const exportMenuRef = useRef<HTMLDivElement>(null);

  // Auto-clear logic (simulated for UI)
  useEffect(() => {
    if (tableData) {
      console.log('Session started for:', tableData.fileName);
      // Load history from localStorage if available for this specific file (optional)
      const savedHistory = localStorage.getItem(`askcsv_history_${tableData.fileName}`);
      if (savedHistory) {
        setQueryHistory(JSON.parse(savedHistory));
      } else {
        setQueryHistory([]);
      }
    }
  }, [tableData]);

  // Save history to local storage when it changes
  useEffect(() => {
    if (tableData && queryHistory.length > 0) {
      localStorage.setItem(`askcsv_history_${tableData.fileName}`, JSON.stringify(queryHistory));
    }
  }, [queryHistory, tableData]);

  // Close export menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (exportMenuRef.current && !exportMenuRef.current.contains(event.target as Node)) {
        setShowExportMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleUploadSuccess = async (data: TableData) => {
    setTableData(data);
    setQueryResult(null);
    try {
      await DataService.initTable(data);
    } catch (err) {
      alert("Error initializing database session.");
    }
  };

  const handleQueryResult = (result: QueryResult, question: string) => {
    setQueryResult(result);

    // Add to history
    const newItem: QueryHistoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      question,
      sql: result.sql,
      explanation: result.explanation,
      timestamp: Date.now(),
    };

    setQueryHistory(prev => {
      // Avoid duplicate questions if they are identical to the last one
      if (prev.length > 0 && prev[0].question === question) return prev;
      return [newItem, ...prev].slice(0, 20); // Keep last 20
    });
  };

  const handleSelectHistoryItem = async (item: QueryHistoryItem) => {
    setSelectedHistoryQuery(item.question);

    // Immediately show the result since we have the SQL stored in history
    // But we need to re-execute it on the current data to get fresh results
    try {
      const results = await DataService.executeQuery(item.sql);
      setQueryResult({
        sql: item.sql,
        explanation: item.explanation,
        data: results
      });
      // Scroll to result
      window.scrollTo({ top: 400, behavior: 'smooth' });
    } catch (err: any) {
      alert("Failed to re-run historical query: " + err.message);
    }
  };

  const handleClearHistory = () => {
    if (confirm("Are you sure you want to clear your query history for this file?")) {
      setQueryHistory([]);
      if (tableData) {
        localStorage.removeItem(`askcsv_history_${tableData.fileName}`);
      }
    }
  };

  const handleDownload = (format: 'csv' | 'xlsx' | 'pdf') => {
    if (!queryResult) return;
    const baseName = 'askcsv_results';

    switch (format) {
      case 'csv':
        DataService.downloadResultAsCSV(queryResult.data, baseName);
        break;
      case 'xlsx':
        DataService.downloadResultAsExcel(queryResult.data, baseName);
        break;
      case 'pdf':
        DataService.downloadResultAsPDF(queryResult.data, baseName);
        break;
    }
    setShowExportMenu(false);
  };

  const reset = () => {
    setTableData(null);
    setQueryResult(null);
    setQueryHistory([]);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-20">
