import { User, AuthState } from '../types';

const USERS_KEY = 'askcsv_users_db';
const CURRENT_USER_KEY = 'askcsv_session';

export class AuthService {
  static signup(email: string, name: string): User {
    const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    if (users.find((u: User) => u.email === email)) {
      throw new Error('User already exists');
    }

    const now = Date.now();
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      email,
      name,
      plan: 'free',
      trialStartDate: now,
      trialEndDate: now + 7 * 24 * 60 * 60 * 1000, // 7 Days
      isSubscriptionActive: false
    };

    users.push(newUser);
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
    this.login(email);
    return newUser;
  }

  static login(email: string): User {
    const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    const user = users.find((u: User) => u.email === email);
    if (!user) throw new Error('User not found');

    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    window.dispatchEvent(new Event('auth-change'));
    return user;
  }

  static logout() {
    localStorage.removeItem(CURRENT_USER_KEY);
    window.dispatchEvent(new Event('auth-change'));
  }

  static getCurrentUser(): User | null {
    const userJson = localStorage.getItem(CURRENT_USER_KEY);
    if (!userJson) return null;
    return JSON.parse(userJson);
  }

  static upgradeToPro(userId: string): User {
    const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    const index = users.findIndex((u: User) => u.id === userId);
    if (index === -1) throw new Error('User not found');

    users[index].plan = 'pro';
    users[index].isSubscriptionActive = true;

    localStorage.setItem(USERS_KEY, JSON.stringify(users));
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(users[index]));
    window.dispatchEvent(new Event('auth-change'));
    return users[index];
  }

  static isTrialActive(user: User): boolean {
    return Date.now() < user.trialEndDate;
  }

  static getRemainingTrialDays(user: User): number {
    const diff = user.trialEndDate - Date.now();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  }
}

