  const [queryHistory, setQueryHistory] = useState<QueryHistoryItem[]>([]);
  const [selectedHistoryQuery, setSelectedHistoryQuery] = useState<string>('');
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isPricingOpen, setIsPricingOpen] = useState(false);
  const [isDocsOpen, setIsDocsOpen] = useState(false);

  const exportMenuRef = useRef<HTMLDivElement>(null);

  // Sync auth state
  useEffect(() => {
    const syncAuth = () => setUser(AuthService.getCurrentUser());
    window.addEventListener('auth-change', syncAuth);
    return () => window.removeEventListener('auth-change', syncAuth);
  }, []);

  useEffect(() => {
    if (tableData) {
      const savedHistory = localStorage.getItem(`askcsv_history_${tableData.fileName}`);
      if (savedHistory) setQueryHistory(JSON.parse(savedHistory));
      else setQueryHistory([]);
    }
  }, [tableData]);

  useEffect(() => {
    if (tableData && queryHistory.length > 0) {
      localStorage.setItem(`askcsv_history_${tableData.fileName}`, JSON.stringify(queryHistory));
    }
  }, [queryHistory, tableData]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (exportMenuRef.current && !exportMenuRef.current.contains(event.target as Node)) {
        setShowExportMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const canDownload = () => {
    if (!user) return false;
    if (user.plan === 'pro') return true;
    return AuthService.isTrialActive(user);
  };

  const handleUploadSuccess = async (data: TableData) => {
    setTableData(data);
    setQueryResult(null);
    try {
      await DataService.initTable(data);
    } catch (err) {
      alert("Error initializing database session.");
    }
  };

  const handleQueryResult = (result: QueryResult, question: string) => {
    setQueryResult(result);
    const newItem: QueryHistoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      question,
      sql: result.sql,
      explanation: result.explanation,
      timestamp: Date.now(),
    };
    setQueryHistory(prev => {
      if (prev.length > 0 && prev[0].question === question) return prev;
      return [newItem, ...prev].slice(0, 20);
    });
  };

  const handleSelectHistoryItem = async (item: QueryHistoryItem) => {
    setSelectedHistoryQuery(item.question);
    try {
      const results = await DataService.executeQuery(item.sql);
      setQueryResult({ sql: item.sql, explanation: item.explanation, data: results });
      window.scrollTo({ top: 400, behavior: 'smooth' });
    } catch (err: any) {
      alert("Failed to re-run historical query: " + err.message);
    }
  };

  const handleDownload = (format: 'csv' | 'xlsx' | 'pdf') => {
    if (!canDownload()) {
      setIsPricingOpen(true);
      return;
    }
    if (!queryResult) return;
    const baseName = 'askcsv_results';
    switch (format) {
      case 'csv': DataService.downloadResultAsCSV(queryResult.data, baseName); break;
      case 'xlsx': DataService.downloadResultAsExcel(queryResult.data, baseName); break;
      case 'pdf': DataService.downloadResultAsPDF(queryResult.data, baseName); break;
    }
    setShowExportMenu(false);
  };

  const reset = () => {
    setTableData(null);
    setQueryResult(null);
    setQueryHistory([]);
  };

  const trialRemaining = user ? AuthService.getRemainingTrialDays(user) : 0;

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-20">
      <Header 
        user={user} 
        onLoginClick={() => setIsAuthModalOpen(true)} 
        onBillingClick={() => setIsPricingOpen(true)}
        onDocsClick={() => setIsDocsOpen(true)}
      />

      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
        onSuccess={() => {}}
      />

      {isPricingOpen && (
        <PricingPage 
          user={user} 
          onClose={() => setIsPricingOpen(false)} 
          onUpgrade={() => setIsPricingOpen(false)}
        />
      )}

      <DocsModal 
        isOpen={isDocsOpen} 
        onClose={() => setIsDocsOpen(false)} 
      />

      {/* Trial Banner */}
      {user && user.plan === 'free' && (
        <div className="max-w-6xl mx-auto px-4 mb-6">
          <div className={`p-4 rounded-2xl flex items-center justify-between border ${trialRemaining > 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-red-50 border-red-100'}`}>
            <div className="flex items-center space-x-3">
              <span className="flex h-3 w-3 relative">
                <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${trialRemaining > 0 ? 'bg-indigo-400' : 'bg-red-400'}`}></span>
                <span className={`relative inline-flex rounded-full h-3 w-3 ${trialRemaining > 0 ? 'bg-indigo-500' : 'bg-red-500'}`}></span>
              </span>
              <p className={`text-sm font-bold ${trialRemaining > 0 ? 'text-indigo-900' : 'text-red-900'}`}>
                {trialRemaining > 0 
                  ? `You are on a 7-day free trial. ${trialRemaining} days remaining.`
                  : `Your free trial has expired. Upgrade to Pro to unlock downloads.`
                }
              </p>
            </div>
            <button 
              onClick={() => setIsPricingOpen(true)}
              className="text-xs font-black uppercase tracking-widest bg-white px-4 py-2 rounded-xl shadow-sm hover:shadow-md transition-all border border-gray-100"
            >
              Upgrade to Pro
            </button>
          </div>
        </div>
      )}

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 space-y-8">
        {!tableData && (
          <div className="text-center py-20 space-y-6 animate-in fade-in slide-in-from-bottom-10 duration-700">
            <h2 className="text-5xl font-black text-gray-900 tracking-tighter sm:text-7xl">
              Turn CSVs into <br/> <span className="text-indigo-600">Conversation.</span>
            </h2>
            <p className="text-xl text-gray-500 max-w-2xl mx-auto font-medium">
              Join 5,000+ data analysts querying millions of rows without writing a single line of SQL.
            </p>
            {!user && (
              <button 
                onClick={() => setIsAuthModalOpen(true)}
                className="mt-8 px-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-2xl shadow-indigo-100 transform hover:scale-105 transition-all"
              >
                Start 7-Day Free Trial
              </button>
            )}
          </div>
        )}

        {!tableData && (
          <div className="max-w-2xl mx-auto w-full">
            <FileUploader 
              onUploadSuccess={handleUploadSuccess} 
              isLoading={isUploading} 
              setIsLoading={setIsUploading} 
            />
          </div>
        )}

        {tableData && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="lg:col-span-1 space-y-6">
              <div className="hidden lg:block bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
                <div className="flex items-center space-x-3 mb-4">
                  <div className="bg-green-100 p-1.5 rounded-md">
                    <svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                  </div>
                  <div className="min-w-0">
                    <h3 className="font-bold text-gray-900 truncate">{tableData.fileName}</h3>
                    <p className="text-[10px] text-gray-500 uppercase tracking-widest">{tableData.rows.length} rows</p>
                  </div>
                </div>
                <button onClick={reset} className="w-full text-center text-xs font-black text-red-500 hover:bg-red-50 py-3 border border-red-50 rounded-xl transition-all">
                  RESET SESSION
                </button>
              </div>
              <QueryHistory history={queryHistory} onSelect={handleSelectHistoryItem} onClear={() => setQueryHistory([])} />
            </div>

            <div className="lg:col-span-2 space-y-8">
              <QueryInterface tableData={tableData} onQueryResult={handleQueryResult} externalQuery={selectedHistoryQuery} />

              {queryResult ? (
                <div className="space-y-6 animate-in zoom-in-95 duration-300">
                  <div className="bg-indigo-50 border border-indigo-100 p-6 rounded-2xl space-y-4 shadow-sm">
                    <div className="flex items-center space-x-2">
                      <div className="bg-indigo-600 p-1 rounded-md text-white font-black text-[10px] uppercase px-2">AI Summary</div>
                    </div>
                    <p className="text-indigo-900 text-sm leading-relaxed font-bold">{queryResult.explanation}</p>
                    <div className="bg-white/80 p-4 rounded-xl border border-indigo-200"><code className="text-xs font-mono text-indigo-700 break-all">{queryResult.sql}</code></div>
                  </div>

                  <div className="flex justify-between items-center px-1">
                    <h4 className="font-black text-gray-900 text-lg">Results</h4>
                    <div className="relative" ref={exportMenuRef}>
                      <button
                        onClick={() => setShowExportMenu(!showExportMenu)}
                        className="flex items-center space-x-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-3 rounded-xl shadow-xl shadow-indigo-100 text-sm font-black transition-all"
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                        <span>Download</span>
                      </button>

                      {showExportMenu && (
                        <div className="absolute right-0 mt-3 w-56 rounded-2xl shadow-2xl bg-white border border-gray-100 z-20 overflow-hidden">
                          <div className="p-1">
                            {['csv', 'xlsx', 'pdf'].map(fmt => (
                              <button
                                key={fmt}
                                onClick={() => handleDownload(fmt as any)}
                                className="w-full text-left px-4 py-3 text-sm font-bold text-gray-700 hover:bg-indigo-50 flex items-center space-x-3"
                              >
                                <span className="bg-gray-100 px-2 py-0.5 rounded text-[10px] font-black uppercase">{fmt}</span>
                                <span>Download as {fmt.toUpperCase()}</span>
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                  <DataTable data={queryResult.data} columns={queryResult.data.length > 0 ? Object.keys(queryResult.data[0]) : tableData.columns.map(c => c.name)} />
                </div>
              ) : (
                <div className="space-y-4">
                  <DataTable data={tableData.rows.slice(0, 5)} columns={tableData.columns.map(c => c.name)} title="Preview" maxRows={5} />
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      <footer className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-gray-100 py-3 px-6 text-center text-[10px] text-gray-400 font-black uppercase tracking-widest z-[50]">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <p>&copy; 2024 AskCSV AI</p>
          <div className="flex items-center space-x-6">
             <span className="flex items-center"><span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-2"></span> Pro Engine Live</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

