declare var Razorpay: any;

export class PaymentService {
  static async processProUpgrade(user: User): Promise<boolean> {
    return new Promise((resolve) => {
      // Razorpay options configuration
      const options = {
        key: "rzp_test_placeholder", // Using a placeholder for demo purposes
        amount: 19900, // Amount in paise (199 INR)
        currency: "INR",
        name: "AskCSV AI",
        description: "Monthly Pro Subscription",
        image: "https://cdn-icons-png.flaticon.com/512/5968/5968260.png",
        handler: function (response: any) {
          // In a real production app, you would verify this on the backend
          console.log("Payment successful:", response.razorpay_payment_id);
          AuthService.upgradeToPro(user.id);
          resolve(true);
        },
        prefill: {
          name: user.name,
          email: user.email,
        },
        notes: {
          address: "Micro-SaaS HQ",
        },
        theme: {
          color: "#4f46e5", // Indigo-600 to match UI
        },
        modal: {
          ondismiss: function() {
            resolve(false);
          }
        }
      };

      try {
        const rzp = new Razorpay(options);
        rzp.open();
      } catch (err) {
        console.error("Razorpay failed to load or open:", err);
        // Fallback for environment where Razorpay script might be blocked
        if (confirm("Razorpay script is not available in this preview environment. Would you like to simulate a successful payment for ₹199?")) {
          AuthService.upgradeToPro(user.id);
          resolve(true);
        } else {
          resolve(false);
        }
      }
    });
  }
}

