import { TableData } from '../types';

// Declare global libraries from index.html
declare var alasql: any;
declare var XLSX: any;
declare var Papa: any;
declare var jspdf: any;

export class DataService {
  private static tableName = 'uploaded_data';

  static async initTable(data: TableData): Promise<void> {
    try {
      // Clear existing table and cache if any
      if (alasql.tables[this.tableName]) {
        alasql(`DROP TABLE ${this.tableName}`);
      }

      // Create table structure with escaped column names
      const colDefs = data.columns.map(col => `\`${col.name}\``).join(', ');
      alasql(`CREATE TABLE ${this.tableName} (${colDefs})`);

      // Bulk insert data - AlaSQL can take the array directly
      alasql.tables[this.tableName].data = data.rows;

      console.log(`Database initialized with ${data.rows.length} rows.`);
    } catch (error) {
      console.error('Error initializing database:', error);
      throw new Error('Failed to initialize database session. Please try re-uploading.');
    }
  }

  static async executeQuery(sql: string): Promise<any[]> {
    try {
      // Security Check: Only allow SELECT
      const trimmedSql = sql.trim().toUpperCase();
      if (!trimmedSql.startsWith('SELECT')) {
        throw new Error('Unauthorized query: Only SELECT statements are allowed for security reasons.');
      }

      // Ensure the table name is correct. Gemini usually gets it right, 
      // but we force our table name for stability.
      let safeSql = sql;
      // Replace case-insensitive references to other table names if they exist
      if (!safeSql.toUpperCase().includes(this.tableName.toUpperCase())) {
         // Fallback regex attempt to swap whatever table was guessed with our real one
         safeSql = safeSql.replace(/FROM\s+([a-zA-Z0-9_]+)/i, `FROM ${this.tableName}`);
      }

      const result = alasql(safeSql);

      // AlaSQL returns nested arrays for some aggregate queries, flatten if necessary
      if (Array.isArray(result) && result.length > 0 && Array.isArray(result[0])) {
          return result[0];
      }

      return Array.isArray(result) ? result : [result];
    } catch (error: any) {
      console.error('SQL Execution Error:', error);
      throw new Error(error.message || 'Error executing the generated SQL. The AI might have used an incompatible syntax.');
    }
  }

  static async downloadResultAsCSV(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;
    const csv = Papa.unparse(data);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    this.triggerDownload(url, `${filename}.csv`);
  }

  static async downloadResultAsExcel(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "QueryResults");
    XLSX.writeFile(workbook, `${filename}.xlsx`);
  }

  static async downloadResultAsPDF(data: any[], filename: string): Promise<void> {
    if (!data || data.length === 0) return;
    const { jsPDF } = jspdf;
    const doc = new jsPDF('l', 'mm', 'a4'); // Landscape for better data fitting
    const columns = Object.keys(data[0]);
    const rows = data.map(item => columns.map(col => item[col]));

    // @ts-ignore
    doc.autoTable({
      head: [columns],
      body: rows,
      theme: 'grid',
      styles: { fontSize: 7, cellPadding: 2 },
      headStyles: { fillColor: [79, 70, 229] }, // Indigo-600
      margin: { top: 25 },
      didDrawPage: (dataArg: any) => {
        doc.setFontSize(16);
        doc.text('AskData AI: Query Results', 14, 15);
        doc.setFontSize(10);
        doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 20);
      }
    });

    doc.save(`${filename}.pdf`);
  }

  private static triggerDownload(url: string, filename: string) {
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
}

import { GoogleGenAI, Type } from "@google/genai";
import { AIResponse, ColumnMetadata } from "../types";

export class GeminiService {
  private static ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  static async generateSQL(
    prompt: string,
    columns: ColumnMetadata[],
    sampleData: any[]
  ): Promise<AIResponse> {
    const schemaString = columns
      .map(c => `- ${c.name} (${c.type})`)
      .join('\n');

    const sampleString = JSON.stringify(sampleData, null, 2);

    const systemInstruction = `
      You are a specialized SQL query assistant for a micro-SaaS called AskData AI.
      Your goal is to convert plain English questions into SAFE, READ-ONLY SELECT SQL queries.

      STRICT RULES:
      1. ONLY generate SELECT statements.
      2. Table name is EXACTLY "uploaded_data".
      3. Use the provided schema ONLY.
      4. Use standard SQL (AlaSQL compatible). Use backticks for column names with spaces: \`Column Name\`.
      5. If the user asks for something that requires modification (UPDATE, DELETE, DROP), refuse politely.
      6. If the question is ambiguous, set isAmbiguous to true and provide a clarificationMessage.
      7. Provide a concise explanation of what the query does in simple English.
      8. Output must be a valid JSON object matching the requested schema.

      Schema:
      ${schemaString}

      Sample Data:
      ${sampleString}
    `;

    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              sql: { type: Type.STRING, description: 'The generated SELECT SQL statement' },
              explanation: { type: Type.STRING, description: 'Brief explanation of the query' },
              isAmbiguous: { type: Type.BOOLEAN, description: 'True if user intent is unclear' },
              clarificationMessage: { type: Type.STRING, description: 'Message asking user for more details if ambiguous' }
            },
            required: ['sql', 'explanation', 'isAmbiguous']
          }
        }
      });

      const result = JSON.parse(response.text);
      return result as AIResponse;
    } catch (error) {
      console.error('Gemini AI Error:', error);
      throw new Error('Failed to generate SQL. Please try phrasing your question differently.');
    }
  }
}

