                <div className="absolute right-0 mt-3 top-full w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 py-2 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2">
                  <div className="px-4 py-3 border-b border-gray-50 bg-gray-50/30">
                    <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Signed in as</p>
                    <p className="text-sm font-bold text-gray-900 truncate">{user.email}</p>

                    <div className="mt-2 flex items-center">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${
                        user.plan === 'pro' 
                          ? 'bg-indigo-100 text-indigo-700' 
                          : isTrialActive 
                            ? 'bg-amber-100 text-amber-700' 
                            : 'bg-red-100 text-red-700'
                      }`}>
                        {user.plan === 'pro' 
                          ? 'Pro Plan' 
                          : isTrialActive 
                            ? `Free Trial (${trialDays} days left)` 
                            : 'Trial Expired'}
                      </span>
                    </div>
                  </div>

                  <button 
                    onClick={() => { setShowMenu(false); onBillingClick(); }} 
                    className="w-full text-left px-4 py-3 text-sm font-bold text-gray-700 hover:bg-gray-50 flex items-center transition-colors"
                  >
                    <svg className="w-4 h-4 mr-3 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
                    </svg>
                    {user.plan === 'pro' ? 'Billing & Subscription' : 'Upgrade to Pro'}
                  </button>

                  <button 
                    onClick={() => { setShowMenu(false); AuthService.logout(); }} 
                    className="w-full text-left px-4 py-3 text-sm font-bold text-red-600 hover:bg-red-50 flex items-center transition-colors"
                  >
                    <svg className="w-4 h-4 mr-3 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                    </svg>
                    Logout
                  </button>
                </div>
              )}
            </div>
          ) : (
            <button 
              onClick={onLoginClick}
              className="px-6 py-2.5 bg-gray-900 hover:bg-black text-white rounded-xl text-sm font-bold transition-all hover:shadow-xl shadow-gray-200 active:scale-95"
            >
              Sign In
            </button>
          )}
        </div>
      </div>
    </header>
  );
};

