import { User } from '../types';
import { AuthService } from './auth';

declare var Stripe: any;

/**
 * PaymentService handles the integration with Stripe Checkout.
 * In this micro-SaaS architecture, we utilize Stripe's pre-built Checkout page
 * to minimize PCI compliance burden and simplify the frontend logic.
 */
export class PaymentService {
  // Use your real Stripe Public Key here (pk_live_... or pk_test_...)
  private static readonly STRIPE_PUBLIC_KEY = 'pk_test_placeholder'; 

  // The price ID from your Stripe Dashboard for the Pro Plan
  private static readonly PRO_PLAN_PRICE_ID = 'price_pro_monthly_199';

  /**
   * Orchestrates the upgrade flow.
   * 1. Initiates session creation (simulated backend call).
   * 2. Redirects user to Stripe Checkout.
   * 3. Handles mock webhook processing for local state persistence.
   */
  static async processProUpgrade(user: User): Promise<boolean> {
    const stripe = typeof Stripe !== 'undefined' ? Stripe(this.STRIPE_PUBLIC_KEY) : null;

    return new Promise(async (resolve) => {
      try {
        console.group('Stripe Upgrade Process');
        console.log('Initiating for user:', user.email);

        // Simulation: API call to our backend to create a Checkout Session
        // In production: const response = await fetch('/api/create-checkout-session', { ... });
        await new Promise(r => setTimeout(r, 1000)); // Simulate network latency

        const mockSessionId = 'cs_test_' + Math.random().toString(36).substring(7);
        console.log('Backend Session Created:', mockSessionId);

        // Simulation: User interaction with Stripe Hosted Page
        const confirmed = confirm(
          `Redirecting to Stripe Secure Checkout...\n\n` +
          `Product: AskData AI Pro Plan\n` +
          `Amount: ₹199 / month (Subscription)\n\n` +
          `Click OK to simulate a successful payment authorized by Stripe.`
        );

        if (!confirmed) {
          console.warn('User cancelled the checkout flow.');
          console.groupEnd();
          return resolve(false);
        }

        // Simulate the delay while user is "on the Stripe page"
        console.log('User navigating on Stripe domain...');
        await new Promise(r => setTimeout(r, 1500));

        // 2. Trigger Mock Webhook Handler
        // In production, Stripe sends an asynchronous POST request to your backend's /webhooks/stripe endpoint.
        // The backend then updates the database. We simulate that update here.
        await this.handleMockStripeWebhook({
          id: 'evt_test_' + Math.random().toString(36).substring(7),
          type: 'checkout.session.completed',
          data: {
            object: {
              id: mockSessionId,
              customer: 'cus_test_' + Math.random().toString(36).substring(7),
              subscription: 'sub_test_' + Math.random().toString(36).substring(7),
              customer_details: { email: user.email },
              status: 'complete',
              payment_status: 'paid'
            }
          }
        });

        console.log('Upgrade flow completed successfully.');
        console.groupEnd();
        resolve(true);
      } catch (err) {
        console.error("Critical Stripe Error:", err);
        alert("Payment processing failed. Please check your connection and try again.");
        console.groupEnd();
        resolve(false);
      }
    });
  }

  /**
   * MOCK WEBHOOK HANDLER (INTERNAL)
   * Mirroring how a production Node.js backend would process Stripe Event objects.
   */
  private static async handleMockStripeWebhook(event: any) {
    console.log(`[Webhook Event] ${event.type} received.`);

    switch (event.type) {
      case 'checkout.session.completed':
        const session = event.data.object;
        if (session.payment_status === 'paid') {
          await this.syncSubscriptionToDB(
            session.customer_details.email, 
            session.subscription, 
            session.customer
          );
        }
        break;

      case 'invoice.payment_succeeded':
        // Handle renewal events
        console.log('Subscription renewed for session:', event.data.object.subscription);
        break;

      case 'customer.subscription.deleted':
        // Handle churn/cancellation
        console.log('Subscription revoked.');
        break;

      default:
        console.log("Unprocessed Stripe event:", event.type);
    }
  }

  /**
   * Persistence logic for simulated database.
   * Updates both the primary record and the current session state.
   */
  private static async syncSubscriptionToDB(email: string, subId: string, cusId: string) {
    const USERS_KEY = 'askcsv_users_db';
    const SESSION_KEY = 'askcsv_session';

    const users: User[] = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    const index = users.findIndex(u => u.email === email);

    if (index !== -1) {
      const updatedUser: User = {
        ...users[index],
        plan: 'pro',
        isSubscriptionActive: true,
        stripeSubscriptionId: subId,
        stripeCustomerId: cusId
      };

      users[index] = updatedUser;
      localStorage.setItem(USERS_KEY, JSON.stringify(users));

      // Update current active session if applicable
      const currentUser: User | null = JSON.parse(localStorage.getItem(SESSION_KEY) || 'null');
      if (currentUser && currentUser.email === email) {
        localStorage.setItem(SESSION_KEY, JSON.stringify(updatedUser));
        // Inform the rest of the application to refresh UI
        window.dispatchEvent(new Event('auth-change'));
      }

      console.log('Database synced with Stripe subscription data.');
    }
  }
}

