        <div className="fixed top-24 right-6 z-[100] animate-in slide-in-from-right-10 duration-500">
          <div className="bg-green-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center space-x-3 border border-green-500">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
            <div>
              <p className="font-black">Success!</p>
              <p className="text-sm opacity-90">Welcome to AskData AI Pro. All features unlocked.</p>
            </div>
          </div>
        </div>
      )}

      {/* Trial Banner - Enhanced Visibility and Actionability */}
      {user && user.plan === 'free' && (
        <div className="max-w-6xl mx-auto px-4 mb-8">
          <div className={`p-6 rounded-[2.5rem] flex flex-col sm:flex-row items-center justify-between border-2 shadow-2xl animate-in slide-in-from-top-4 duration-500 transition-all ${
            trialRemaining > 0 
              ? 'bg-indigo-50 border-indigo-100 shadow-indigo-100/30' 
              : isGraceActive
                ? 'bg-amber-50 border-amber-200 shadow-amber-100/30'
                : 'bg-red-50 border-red-300 shadow-red-200/50'
          }`}>
            <div className="flex items-center space-x-5 mb-6 sm:mb-0">
              <div className={`p-4 rounded-3xl flex-shrink-0 ${
                trialRemaining > 0 ? 'bg-indigo-100' : isGraceActive ? 'bg-amber-100' : 'bg-red-100'
              }`}>
                <span className="flex h-6 w-6 relative">
                  <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${
                    trialRemaining > 0 ? 'bg-indigo-400' : isGraceActive ? 'bg-amber-400' : 'bg-red-500'
