                                Upgrade to Pro to unlock these export options
                              </div>
                            )}
                            {['csv', 'xlsx', 'pdf'].map(fmt => (
                              <button
                                key={fmt}
                                onClick={() => handleDownload(fmt as any)}
                                className={`w-full text-left px-4 py-3 text-sm font-bold rounded-xl flex items-center justify-between transition-colors ${
                                  downloadAllowed 
                                  ? 'text-gray-700 hover:bg-indigo-50' 
                                  : 'text-gray-400 hover:bg-red-50'
                                }`}
                              >
                                <div className="flex items-center space-x-3">
                                  <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${
                                    downloadAllowed ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-100 text-gray-400'
                                  }`}>{fmt}</span>
                                  <span>{fmt.toUpperCase()} Export</span>
                                </div>
                                {!downloadAllowed && (
                                  <svg className="w-3.5 h-3.5 text-red-400" fill="currentColor" viewBox="0 0 20 20">
                                    <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
                                  </svg>
                                )}
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                  <DataTable data={queryResult.data} columns={queryResult.data.length > 0 ? Object.keys(queryResult.data[0]) : tableData.columns.map(c => c.name)} />
                </div>
              ) : (
                <div className="space-y-4">
                  <DataTable data={tableData.rows.slice(0, 5)} columns={tableData.columns.map(c => c.name)} title="Preview" maxRows={5} />
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      <footer className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-gray-100 py-3 px-6 text-center text-[10px] text-gray-400 font-black uppercase tracking-widest z-[50]">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <p>&copy; 2024 AskData AI</p>
          <div className="flex items-center space-x-6">
             <span className="flex items-center"><span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-2"></span> Pro Engine Live</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

