import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import DataTable from './components/DataTable';
import QueryInterface from './components/QueryInterface';
import QueryHistory from './components/QueryHistory';
import AuthModal from './components/AuthModal';
import PricingPage from './components/PricingPage';
import DocsModal from './components/DocsModal';
import { TableData, QueryResult, QueryHistoryItem, User } from './types';
import { DataService } from './services/db';
import { AuthService } from './services/auth';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(AuthService.getCurrentUser());
  const [tableData, setTableData] = useState<TableData | null>(null);
  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [queryHistory, setQueryHistory] = useState<QueryHistoryItem[]>([]);
  const [selectedHistoryQuery, setSelectedHistoryQuery] = useState<string>('');
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isPricingOpen, setIsPricingOpen] = useState(false);
  const [isDocsOpen, setIsDocsOpen] = useState(false);
  const [showSuccessToast, setShowSuccessToast] = useState(false);

  const exportMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const syncAuth = () => setUser(AuthService.getCurrentUser());
    window.addEventListener('auth-change', syncAuth);
    return () => window.removeEventListener('auth-change', syncAuth);
  }, []);

  useEffect(() => {
    if (tableData) {
      const savedHistory = localStorage.getItem(`askdata_history_${tableData.fileName}`);
      if (savedHistory) setQueryHistory(JSON.parse(savedHistory));
      else setQueryHistory([]);
    }
  }, [tableData]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (exportMenuRef.current && !exportMenuRef.current.contains(event.target as Node)) {
        setShowExportMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const canDownload = () => {
    if (!user) return false;
    if (user.plan === 'pro') return true;
    return AuthService.isTrialActive(user) || AuthService.isGracePeriodActive(user);
  };

  const handleUploadSuccess = async (data: TableData) => {
    setTableData(data);
    setQueryResult(null);
    try {
      await DataService.initTable(data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleQueryResult = (result: QueryResult, question: string) => {
    setQueryResult(result);
    const newItem: QueryHistoryItem = {
      id: Math.random().toString(36).substr(2, 9),
      question,
      sql: result.sql,
      explanation: result.explanation,
      timestamp: Date.now(),
    };
    setQueryHistory(prev => [newItem, ...prev].slice(0, 20));
    localStorage.setItem(`askdata_history_${tableData?.fileName}`, JSON.stringify([newItem, ...queryHistory].slice(0, 20)));
  };

  const handleDownload = (format: 'csv' | 'xlsx' | 'pdf') => {
    if (!canDownload()) {
      setIsPricingOpen(true);
      return;
    }
    if (!queryResult) return;
    const baseName = 'askdata_export';
    switch (format) {
      case 'csv': DataService.downloadResultAsCSV(queryResult.data, baseName); break;
      case 'xlsx': DataService.downloadResultAsExcel(queryResult.data, baseName); break;
      case 'pdf': DataService.downloadResultAsPDF(queryResult.data, baseName); break;
    }
    setShowExportMenu(false);
  };

  const trialRemaining = user ? AuthService.getRemainingTrialDays(user) : 0;
  const isGraceActive = user ? AuthService.isGracePeriodActive(user) : false;
  const downloadAllowed = canDownload();

  return (
    <div className="min-h-screen pb-24">
      <Header 
        user={user} 
        onLoginClick={() => setIsAuthModalOpen(true)} 
        onBillingClick={() => setIsPricingOpen(true)}
        onDocsClick={() => setIsDocsOpen(true)}
      />

      <AuthModal isOpen={isAuthModalOpen} onClose={() => setIsAuthModalOpen(false)} onSuccess={() => {}} />
      <DocsModal isOpen={isDocsOpen} onClose={() => setIsDocsOpen(false)} />
      {isPricingOpen && (
        <PricingPage 
          user={user} 
          onClose={() => setIsPricingOpen(false)} 
          onUpgrade={() => setShowSuccessToast(true)}
          onLoginRequired={() => { setIsPricingOpen(false); setIsAuthModalOpen(true); }}
        />
      )}

      {showSuccessToast && (
        <div className="fixed top-24 right-6 z-[100] animate-bounce bg-green-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center space-x-3 border border-green-500">
          <span className="font-bold">Success! Welcome to Pro.</span>
          <button onClick={() => setShowSuccessToast(false)} className="hover:opacity-75">✕</button>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-6 space-y-8">
        {!tableData ? (
          <div className="py-24 flex flex-col items-center justify-center text-center space-y-12">
            <div className="space-y-4 max-w-3xl">
              <h2 className="text-6xl font-extrabold text-slate-900 tracking-tight leading-tight">
                Talk to your <span className="text-indigo-600">Spreadsheets</span> like a human.
              </h2>
              <p className="text-xl text-slate-500 font-medium">
                Upload your CSV or Excel files and ask questions in plain English. 
                AskData AI handles the complex SQL and data processing instantly.
              </p>
            </div>

            <div className="w-full max-w-xl">
              <FileUploader 
                onUploadSuccess={handleUploadSuccess} 
                isLoading={isUploading} 
                setIsLoading={setIsUploading} 
              />
            </div>

            <div className="flex items-center space-x-8 text-slate-400 font-bold uppercase tracking-widest text-xs">
              <span className="flex items-center"><span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span> Browser-Side SQL</span>
              <span className="flex items-center"><span className="w-2 h-2 bg-blue-500 rounded-full mr-2"></span> Gemini 3.0 Pro</span>
              <span className="flex items-center"><span className="w-2 h-2 bg-indigo-500 rounded-full mr-2"></span> Zero Server Storage</span>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <aside className="lg:col-span-1 space-y-6">
              <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col space-y-4">
                <div className="flex items-center space-x-3">
                   <div className="p-2 bg-indigo-50 rounded-xl text-indigo-600">
                     <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                   </div>
                   <div className="truncate">
                     <p className="text-sm font-bold text-slate-900 truncate">{tableData.fileName}</p>
                     <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider">{tableData.rows.length} rows detected</p>
                   </div>
                </div>
                <button 
                  onClick={() => setTableData(null)}
                  className="w-full py-3 bg-slate-50 hover:bg-red-50 text-slate-400 hover:text-red-500 font-bold text-xs rounded-2xl transition-all uppercase tracking-widest border border-slate-100"
                >
                  Clear Dataset
                </button>
              </div>
              <QueryHistory history={queryHistory} onSelect={(item) => setSelectedHistoryQuery(item.question)} onClear={() => setQueryHistory([])} />
            </aside>

            <section className="lg:col-span-3 space-y-8">
              <QueryInterface tableData={tableData} onQueryResult={handleQueryResult} externalQuery={selectedHistoryQuery} />

              {queryResult ? (
                <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
                  <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-4">
                    <div className="flex items-center justify-between">
                       <h3 className="font-bold text-slate-900 flex items-center">
                         <span className="w-2 h-6 bg-indigo-600 rounded-full mr-3"></span> Result Preview
                       </h3>
                       <div className="relative" ref={exportMenuRef}>
                          <button
                            onClick={() => setShowExportMenu(!showExportMenu)}
                            className={`flex items-center space-x-2 px-6 py-2.5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all ${
                              downloadAllowed 
                              ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-100' 
                              : 'bg-red-600 text-white hover:bg-red-700'
                            }`}
                          >
                            <span>{downloadAllowed ? 'Export Data' : 'Unlock Export'}</span>
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7"/></svg>
                          </button>
                          {showExportMenu && (
                            <div className="absolute right-0 mt-3 w-56 glass-panel rounded-2xl shadow-2xl z-50 overflow-hidden ring-1 ring-slate-200">
                               {['csv', 'xlsx', 'pdf'].map(fmt => (
                                 <button 
                                   key={fmt} 
                                   onClick={() => handleDownload(fmt as any)}
                                   className="w-full text-left px-5 py-4 text-sm font-bold text-slate-700 hover:bg-indigo-50 flex items-center space-x-3 transition-colors"
                                 >
                                   <span className="bg-slate-100 px-2 py-0.5 rounded text-[10px] font-black uppercase text-slate-500">{fmt}</span>
                                   <span>Download as {fmt.toUpperCase()}</span>
                                 </button>
                               ))}
                            </div>
                          )}
                       </div>
                    </div>
                    <DataTable data={queryResult.data} columns={Object.keys(queryResult.data[0] || {})} />
                  </div>
                </div>
              ) : (
                <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <DataTable data={tableData.rows.slice(0, 10)} columns={tableData.columns.map(c => c.name)} title="Dataset Preview (First 10 Rows)" />
                </div>
              )}
