                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                </div>
                <p className="text-sm font-bold">
                  {trialRemaining > 0 
                    ? `PRO TIP: You have ${trialRemaining} days left in your full-featured trial.` 
                    : isGraceActive 
                      ? "YOUR TRIAL HAS ENDED. We've granted you a 3-day grace period for exports!" 
                      : "TRIAL EXPIRED. Upgrade to Pro to continue querying and exporting data."}
                </p>
             </div>
             <button onClick={() => setIsPricingOpen(true)} className="bg-white text-slate-900 px-6 py-2 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-indigo-50 transition-colors mr-2">
               Upgrade
             </button>
          </div>
        </div>
      )}

      <footer className="fixed bottom-0 left-0 right-0 py-3 bg-white/60 backdrop-blur-sm border-t border-slate-100 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 text-center z-40">
        &copy; 2024 ASKDATA AI &bull; SECURE DATA ANALYTICS
      </footer>
    </div>
  );
};

