import React, { useRef, useState } from 'react';
import { TableData, ColumnMetadata } from '../types';

interface Props {
  onUploadSuccess: (data: TableData) => void;
  isLoading: boolean;
  setIsLoading: (val: boolean) => void;
}

declare var XLSX: any;
declare var Papa: any;

const FileUploader: React.FC<Props> = ({ onUploadSuccess, isLoading, setIsLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [statusMessage, setStatusMessage] = useState('Detecting columns...');

  const detectType = (value: any): ColumnMetadata['type'] => {
    if (value === null || value === undefined) return 'string';
    if (typeof value === 'number') return 'number';
    if (typeof value === 'boolean') return 'boolean';
    if (typeof value === 'string') {
      const date = Date.parse(value);
      if (!isNaN(date) && value.length > 8 && (value.includes('-') || value.includes('/') || value.includes(':'))) {
        return 'date';
      }
    }
    return 'string';
  };

  const validateAndProcessFile = (file: File) => {
    if (file.size > 10 * 1024 * 1024) {
      alert("File is too large. Please upload a file smaller than 10MB.");
      return;
    }

    setIsLoading(true);
    setStatusMessage('Reading file structure...');
    const extension = file.name.split('.').pop()?.toLowerCase();

    // Small timeout to allow UI to update
    setTimeout(() => {
      if (extension === 'csv') {
        setStatusMessage('Parsing CSV rows...');
        Papa.parse(file, {
          header: true,
          dynamicTyping: true,
          skipEmptyLines: true,
          complete: (results: any) => {
            processParsedData(results.data, file.name);
          },
          error: (err: any) => {
            console.error(err);
            alert("Error parsing CSV: " + err.message);
            setIsLoading(false);
          }
        });
      } else if (['xlsx', 'xls', 'ods'].includes(extension || '')) {
        setStatusMessage('Reading Excel sheets...');
        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const data = new Uint8Array(event.target?.result as ArrayBuffer);
            const workbook = XLSX.read(data, { type: 'array' });
            const firstSheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[firstSheetName];
            const jsonData = XLSX.utils.sheet_to_json(worksheet);
            processParsedData(jsonData, file.name);
          } catch (err: any) {
            alert("Error reading Excel file: " + err.message);
            setIsLoading(false);
          }
        };
        reader.readAsArrayBuffer(file);
      } else {
        alert('Unsupported file format. Please upload CSV or Excel.');
        setIsLoading(false);
      }
    }, 300);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) validateAndProcessFile(file);
  };

  const handleDragOver = (e: React.DragOverEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!isLoading) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    if (isLoading) return;

    const file = e.dataTransfer.files?.[0];
    if (file) validateAndProcessFile(file);
  };

  const processParsedData = (rows: any[], fileName: string) => {
    setStatusMessage('Finalizing data model...');
    if (!rows || rows.length === 0) {
      alert('The file appears to be empty or could not be read properly.');
      setIsLoading(false);
      return;
    }

    const cleanedRows = rows.map(row => {
        const newRow: any = {};
        for (const key in row) {
            const val = row[key];
            if (val !== null && typeof val === 'object' && !(val instanceof Date)) {
                newRow[key] = JSON.stringify(val);
            } else {
                newRow[key] = val;
            }
        }
        return newRow;
    });

    const firstRow = cleanedRows[0];
    const columns: ColumnMetadata[] = Object.keys(firstRow).map(key => ({
      name: key,
      type: detectType(firstRow[key])
    }));

    onUploadSuccess({ columns, rows: cleanedRows, fileName });
    setIsLoading(false);
  };

  return (
    <div 
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`bg-white p-10 rounded-2xl border-2 transition-all duration-200 shadow-xl relative overflow-hidden
        ${isDragging 
          ? 'border-indigo-500 bg-indigo-50 scale-[1.02]' 
          : 'border-gray-200 hover:border-indigo-300'
        }`}
    >
      {isLoading && (
        <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center space-y-4 animate-in fade-in duration-300">
           <div className="relative">
              <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                 <svg className="w-6 h-6 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"/>
                 </svg>
              </div>
           </div>
           <div className="text-center">
             <p className="text-sm font-black text-slate-900 uppercase tracking-widest">{statusMessage}</p>
             <p className="text-xs text-slate-400 font-bold mt-1">Please keep this tab open</p>
           </div>
        </div>
      )}

      <div className="flex flex-col items-center justify-center space-y-6">
        <div className={`p-5 rounded-2xl transition-colors duration-200 ${isDragging ? 'bg-indigo-600' : 'bg-indigo-50'}`}>
          <svg 
            className={`w-14 h-14 transition-colors duration-200 ${isDragging ? 'text-white' : 'text-indigo-600'}`} 
            fill="none" 
            stroke="currentColor" 
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 13h6m-3-3v6m5 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
        </div>
        <div className="text-center space-y-2">
          <h3 className="text-2xl font-bold text-gray-900">
            {isDragging ? 'Drop it here!' : 'Upload Data'}
          </h3>
          <p className="text-gray-500 max-w-sm">
            Drag and drop your CSV or Excel file here, or click to browse.
          </p>
        </div>

        <div className="w-full">
          <input 
            type="file" 
            className="hidden" 
            ref={fileInputRef} 
            accept=".csv,.xlsx,.xls,.ods" 
            onChange={handleFileChange} 
          />
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={isLoading}
            className={`w-full flex items-center justify-center space-x-2 px-6 py-4 rounded-xl border-2 border-dashed transition-all 
              ${isLoading 
                ? 'bg-gray-50 border-gray-200 cursor-not-allowed opacity-50' 
                : isDragging
                  ? 'bg-white border-indigo-400 text-indigo-700'
                  : 'bg-indigo-50/50 border-indigo-200 hover:border-indigo-500 hover:bg-indigo-50 text-indigo-700'
              }`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
            <span className="font-semibold">Select or Drop File</span>
          </button>
        </div>
        <p className="text-xs text-gray-400">Supported formats: .csv, .xlsx, .xls</p>
      </div>
    </div>
  );
};

export default FileUploader;

import React, { useState, useEffect } from 'react';
import { GeminiService } from '../services/gemini.ts';
import { DataService } from '../services/db.ts';
import { TableData, QueryResult } from '../types.ts';

interface Props {
  tableData: TableData;
  onQueryResult: (result: QueryResult, question: string) => void;
  externalQuery?: string;
}

const QueryInterface: React.FC<Props> = ({ tableData, onQueryResult, externalQuery }) => {
  const [query, setQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [processingStatus, setProcessingStatus] = useState<'ai' | 'sql' | 'idle'>('idle');

  useEffect(() => {
    if (externalQuery) {
      setQuery(externalQuery);
    }
  }, [externalQuery]);

  const handleAsk = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!query.trim() || isProcessing) return;

    setIsProcessing(true);
    setProcessingStatus('ai');
    setError(null);

    try {
      // 1. Get SQL from AI
      const aiResponse = await GeminiService.generateSQL(
        query,
        tableData.columns,
        tableData.rows.slice(0, 5)
      );

      if (aiResponse.isAmbiguous) {
        setError(`I'm not sure what you meant: ${aiResponse.clarificationMessage || "Could you rephrase that?"}`);
        setIsProcessing(false);
        setProcessingStatus('idle');
        return;
      }

      setProcessingStatus('sql');
      // 2. Execute SQL via DataService
      const results = await DataService.executeQuery(aiResponse.sql);

      // 3. Update Parent
      onQueryResult({
        sql: aiResponse.sql,
        explanation: aiResponse.explanation,
        data: results
      }, query);
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred while processing your question.');
    } finally {
      setIsProcessing(false);
      setProcessingStatus('idle');
    }
  };

  const suggestions = [
    "Summarize the data",
    "List top 5 records",
    "How many entries in total?",
    "Filter by specific value"
  ];

  return (
    <div className="bg-white p-8 rounded-2xl border border-gray-200 shadow-lg space-y-6 relative">
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2 text-indigo-600">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
             </svg>
             <h3 className="font-bold uppercase tracking-widest text-xs">AI Data Assistant</h3>
          </div>
          {isProcessing && (
            <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-widest text-indigo-500 animate-pulse">
               <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></span>
               <span>{processingStatus === 'ai' ? 'Gemini is thinking...' : 'Executing SQL engine...'}</span>
            </div>
          )}
        </div>

        <form onSubmit={handleAsk} className="relative group">
          <input
            type="text"
            className={`w-full pl-6 pr-32 py-5 border-2 rounded-2xl text-lg font-medium outline-none transition-all
              ${error 
                ? 'border-red-200 focus:border-red-500 bg-red-50/30 text-red-900' 
                : 'border-gray-100 focus:border-indigo-500 bg-gray-50/50 focus:bg-white shadow-inner focus:shadow-md text-indigo-950'
              } disabled:opacity-75 disabled:cursor-not-allowed`}
            placeholder="Ask anything about your file..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            disabled={isProcessing}
          />
          <button
            type="submit"
            disabled={isProcessing || !query.trim()}
            className="absolute right-3 top-3 bottom-3 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-400 text-white font-bold py-2 px-6 rounded-xl transition-all shadow-md hover:shadow-lg active:scale-95 flex items-center justify-center min-w-[100px]"
          >
            {isProcessing ? (
              <svg className="animate-spin h-6 w-6 text-white" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            ) : (
              'Ask'
            )}
          </button>
        </form>
      </div>

      {error && (
        <div className="animate-in fade-in slide-in-from-top-2 duration-300 p-4 bg-red-50 border border-red-100 text-red-700 rounded-xl text-sm flex items-start space-x-3 shadow-sm">
          <svg className="w-5 h-5 mt-0.5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
          </svg>
          <div className="flex-1">
            <p className="font-semibold">Oops!</p>
            <p className="opacity-90">{error}</p>
          </div>
        </div>
      )}

      <div className="flex flex-wrap gap-3">
        {suggestions.map((s, i) => (
          <button
            key={i}
            onClick={() => { setQuery(s); }}
            disabled={isProcessing}
